"""
Summarize UCCSD hardware-aware (all2all, hhex, square) benchmarking results from some compiler
"""

import sys

sys.path.append("..")

import os
import argparse
import pandas as pd
from natsort import natsorted
from qiskit import QuantumCircuit

# Original-circuit reference = the naive pass output (raw Trotter circuits),
# generated by `make naive` — replaces the retired benchmarks/uccsd_qasm dir.
BENCHMARK_DPATH = "./output_uccsd/naive/all2all"
OUTPUT_DPATH = "./output_uccsd/"

parser = argparse.ArgumentParser(prog="Summarize compilation results (gate count and circuit depth statistics)")
parser.add_argument("-c", "--compiler", type=str, help="Compiler name")
args = parser.parse_args()

OUTPUT_DPATH = os.path.join(OUTPUT_DPATH, args.compiler)

if not os.path.isdir(OUTPUT_DPATH):
    raise ValueError("{} does not exist".format(OUTPUT_DPATH))
if not os.path.isdir(BENCHMARK_DPATH) or not any(
    f.endswith(".qasm") for f in os.listdir(BENCHMARK_DPATH)
):
    raise ValueError(
        "{} is missing or empty — run `make naive` first to generate the "
        "original-circuit reference (note: it is empty after an old-style "
        "`make clean`)".format(BENCHMARK_DPATH)
    )

os.makedirs("./results", exist_ok=True)
result_fname = "./results/result_uccsd_{}.csv".format(args.compiler)

results = {
    "all2all": pd.DataFrame(columns=["program", "num_gates", "num_2q_gates", "depth", "depth_2q"]),
    "all2all_opt": pd.DataFrame(columns=["program", "num_gates", "num_2q_gates", "depth", "depth_2q"]),
    "hhex": pd.DataFrame(columns=["program", "num_gates", "num_2q_gates", "depth", "depth_2q"]),
    "square": pd.DataFrame(columns=["program", "num_gates", "num_2q_gates", "depth", "depth_2q"]),
}


for dir in ["all2all", "all2all_opt", "hhex", "square"]:
    output_dpath = os.path.join(OUTPUT_DPATH, dir)
    if not os.path.isdir(output_dpath):
        print("Skipping", output_dpath, "(not generated for this compiler)")
        continue
    print("Processing", output_dpath)
    for fname in natsorted(os.listdir(output_dpath)):
        if not fname.endswith(".qasm"):
            continue
        program_name = fname.replace(".qasm", "")
        output_circ_file = os.path.join(output_dpath, fname)
        circ = QuantumCircuit.from_qasm_file(output_circ_file)

        results[dir] = pd.concat(
            [
                results[dir],
                pd.DataFrame(
                    {
                        "program": program_name,
                        "num_gates": circ.size(),
                        "num_2q_gates": circ.num_nonlocal_gates(),
                        "depth": circ.depth(),
                        "depth_2q": circ.depth(lambda instr: instr.operation.num_qubits > 1),
                    },
                    index=[0],
                ),
            ],
            ignore_index=True,
        )

# initially, this data frame contains information of original circuits
result = pd.DataFrame(columns=["program", "num_qubits", "num_gates", "num_2q_gates", "depth", "depth_2q"])
for fname in natsorted(os.listdir(BENCHMARK_DPATH)):
    if not fname.endswith(".qasm"):
        continue
    program_name = fname.split(".")[0]
    program_name = program_name.replace("_sto3g", "")  # simplify the name

    qasm_file = os.path.join(BENCHMARK_DPATH, fname)
    circ = QuantumCircuit.from_qasm_file(qasm_file)

    result = pd.concat(
        [
            result,
            pd.DataFrame(
                {
                    "program": program_name,
                    "num_qubits": circ.num_qubits,
                    "num_gates": circ.size(),
                    "num_2q_gates": circ.num_nonlocal_gates(),
                    "depth": circ.depth(),
                    "depth_2q": circ.depth(lambda instr: instr.operation.num_qubits > 1),
                },
                index=[0],
            ),
        ],
        ignore_index=True,
    )


# merge only the topologies actually generated for this compiler
for dir in ["all2all", "all2all_opt", "hhex", "square"]:
    if results[dir].empty:
        continue
    result = pd.merge(result, results[dir], on="program", suffixes=("", "({})".format(dir)))

result.to_csv(result_fname, index=False)
print("Saved to", result_fname)
